// GENERATED from docs/research/coaching/pass5-*.json (117 coaching articles, videos and courses; BAK's own words).
// More keys, faults, drills and pro tips per skill, plus where coaches disagree. Merged into coachingKnowledge().
export const coachingPass5:Record<string,{keys?:string[];faults?:{fault:string;looks_like?:string;why?:string;fix?:string;drill?:string}[];drills?:{name:string;how?:string;progression?:string;done_when?:string}[];pro_tips?:string[];coaches_differ?:string[]}>={"starts":{"keys":["Stage the clutch: in gear, ease the lever out until the bike just starts to creep, then pull it back a touch so you sit right at the bite point when the gate drops.","Fingers: some coaches run three fingers on the clutch with the index finger on the grip to hold the body forward; others use two. Pick one and keep it the same every start.","Meter drive with the clutch, not the throttle: hold steady revs and use the lever to control wheelspin and front lift; it reacts faster than the throttle.","Aim for a front wheel just skimming a few inches up; no lift at all usually means there was more drive to use, a big wheelie means slip the clutch or ease off.","Brief ease of drive as the rear tire crosses the gate slot, then full drive once it is on the dirt.","Eyes: rest them on a spot just in front of the gate so the drop shows in peripheral vision; do not stare at the gate for long before it falls.","Rut behind the gate: level, packed and straight, front wheel aligned with it, rear centered; no ramp shape and no deep hole.","Grippy pad: lean forward with elbows high, lock the legs and core so the hips cannot slide back. Slippery pad: torso more upright, smoother throttle and clutch, both feet down for balance.","Concrete: sweep the spot clean, keep throttle low (roughly a quarter to half), release the clutch gently until the rear reaches dirt, then get forward and on the gas. A holeshot device is generally not used on concrete.","Get the feet onto the pegs quickly once driving; the first shift timing depends on the surface (too early in mud bogs the bike)."],"faults":[{"fault":"Hips slide back off the drop","looks_like":"Rear of the seat under the rider in the first metres, front climbing.","why":"No leg and core lock on a grippy pad; arms holding the rider on.","fix":"Lock heels and knees against the bike, chest forward, elbows high before the drop.","drill":"Film side-on starts and check hip position on the seat at the first frame of motion."},{"fault":"Wheelspin off a slick or concrete pad","looks_like":"Rear spinning in place, bike slow to move, rear stepping sideways.","why":"Too many revs or dumped clutch; leaning over the bar pad on a slick start.","fix":"Fewer revs, gentle clutch, torso more upright to weight the rear; open up once on dirt.","drill":"Alternate practice starts on a slick and a grippy surface, noting revs used on each."},{"fault":"Jerky release or let-go clutch","looks_like":"Bike surges then bogs, or wheelies then drops.","why":"Slipping the clutch out partly and then dropping it, or relying on the throttle for control.","fix":"One smooth, full release from the staged bite point; hold the throttle steady and use the clutch to fine-tune."},{"fault":"Ramped or holed gate rut","looks_like":"Front lifting early or the bike rolling into the gate before the drop.","why":"Rut built as a ramp, or a deep hole left behind the gate.","fix":"Fill and pack the rut level and straight; only build a small lip if the coach or surface calls for it."},{"fault":"Checking up off the gate","looks_like":"Rider rolls off when the front lifts or body position is imperfect; others drive past.","why":"Reacting to a small wheelie by closing the throttle.","fix":"Stay on the gas and correct with body weight and a touch of clutch instead of shutting off."}],"drills":[{"name":"Start every lap","how":"At practice, begin each lap or each moto with a start from a gate or line.","progression":"Start with clutch release only, then add gate reaction, then add the first turn.","done_when":"Starts feel the same every time and are no longer a separate event."},{"name":"Five perfect in a row","how":"Count consecutive starts that meet your checklist (body forward, small wheelie, straight, quick feet up); any mistake resets the count to one.","progression":"Raise the target count or add a gate and other riders.","done_when":"Five clean starts in a row without a reset."},{"name":"Surface pair","how":"Do practice starts on both a slick and a grippy surface and note what revs and body position worked for each.","progression":"Limit grippy-pad starts to protect the clutch; quality over quantity.","done_when":"You can say before the gate which setting you will use for the pad in front of you."},{"name":"Gate timing study","how":"Watch earlier motos and count how long the gate takes to fall after the card turns.","progression":"Use it to set when you bring revs up.","done_when":"You are ready at the bite point every time the gate falls, without anticipating it."}],"pro_tips":["Hold the clutch at the bite point with steady revs; most of the start is clutch and traction, not throttle.","Use the rev-indicator light, where the bike has one, because you cannot hear your own engine on a full gate.","Practise starts a day or session before the race and build belief in a routine; reaction time is less important than what you do once moving.","On concrete, a short controlled spin to clean the tire is better than a long burnout that wears it.","Lightly holding the front brake while bringing the clutch to the bite point keeps the bike still against the gate.","Lighter riders get less grip on a slick gate, so throttle control matters even more for them."],"coaches_differ":["Feet at the gate: MXA has both feet forward on the pegs, MotoOnline has both feet down, BCP has feet angled about 45 degrees with heels hooked under the pegs on grippy pads and both feet down on slippery ones. The current skill says pegs or one foot ready; treat it as surface- and rider-dependent.","Gear: MXA and MotoOnline use second; Semics says first or second; the current skill already covers taller gears on slick pads.","Rut ramp at the gate: Semics builds a small ramp at the gate for traction; MotoOnline usually skips it except in sand; MXA warns against a ramp-shaped rut.","Rut on faster bikes: MXA keeps the rut on faster bikes for sidewall grip but flattens it for a slow 125 so the rear can spin up.","Shifting: MotoOnline has holeshot riders stay pinned and shift without the clutch to stay in the power; others say short-shift. Clutchless upshifts add drivetrain wear."]},"braking":{"keys":["Set the body before the brakes: stand, hips back and a little space between you and the seat so a bump cannot throw you forward, then brake.","Close the throttle fully, then squeeze the front and press the rear progressively to just short of lock-up, both wheels still turning.","Downshift once braking is under control, so you exit in the right gear.","Front does most of the stopping (MXA gives roughly 70 to 80 percent); the rear steers, settles the bike over bumps and helps keep the engine running.","Brake for the entry speed you need, not simply as late as possible; slightly early beats overshooting.","Surface sets the marker: later on grippy loam or grass, earlier and lighter on slick hardpack and off-cambers.","Look further ahead while braking to pick the line with the fewest bumps; a smoother line that lets you brake harder can beat the direct one.","Into a rutted corner, brake standing with the bike fairly upright and lean only once both wheels are tracking in the rut.","Release the rear brake at the transition from braking to drive and put the foot back on the peg; control then comes from clutch, throttle and body.","Engine braking: on a four-stroke keeping the clutch out uses the engine to help slow the bike and loads the front for bite in ruts; pull the clutch in for crawl-speed corners or a brake slide so it does not stall.","Engine braking also stiffens the rear over braking bumps and can make it chatter or hop; downshifting late or pulling the clutch reduces it.","Small braking bumps can be bounced like small whoops; big, spaced ones can be ridden like a rhythm section. Scrub speed before the bumps where you can rather than braking hard through them.","Land from a jump before a turn slightly front-first, let the front settle, then build front brake; braking hard on an unloaded front can tuck it or lift the rear."],"faults":[{"fault":"Braking before the body is set","looks_like":"Rider upright or weight forward as the fork dives; elbows locked.","why":"Hitting the brakes before moving back and bracing.","fix":"Stand, hips back and brace legs first, then brake.","drill":"Straight-line stops from a marker, filming side-on, checking body position before the first brake frame."},{"fault":"Sitting down to brake","looks_like":"Rider seated in the braking bumps, bouncing on the seat.","why":"Tired or habit; sitting early for the turn.","fix":"Stay standing through braking and sit only as you come off the brakes."},{"fault":"Nose wheelie into the turn","looks_like":"Rear high, front compressed, rider pitched forward, often after landing on the front wheel or hitting a roller under hard braking.","why":"Hard front brake while the front is the only wheel down, or braking over a bump.","fix":"Do the hard braking before the roller or bump, and ease the front brake over a single big bump before reapplying."},{"fault":"Braking points creeping earlier","looks_like":"Lap times fade as the moto goes on; rider off the brakes and coasting before the turn.","why":"Fatigue and losing trust in the front.","fix":"Use a fixed marker (bale, rock, bump) and keep it each lap."},{"fault":"Dragging the rear brake through the corner","looks_like":"Rear foot still on the pedal past the apex; bike slow to drive; leg kicked out.","why":"Using the rear brake as a crutch; no roll speed.","fix":"Come off the rear before or at the transition and let roll speed carry you; get on the gas.","drill":"Section laps with no rear brake to build roll speed."},{"fault":"Rear steps out then straightens repeatedly","looks_like":"Rear slides, rider lets off, bike straightens and the cycle repeats into the turn.","why":"Clutch pulled in at speed on a slick approach so there is no engine braking to steady the rear.","fix":"Keep the clutch out at speed, modulate the rear just short of lock."},{"fault":"Too much rear brake making the bike stand up","looks_like":"Bike standing up and running wide on entry.","why":"Heavy rear brake or turning in at too sharp an angle.","fix":"Lighter rear, more front, use the width of the track."}],"drills":[{"name":"Front-only and rear-only stops","how":"On a straight, stop to a full halt using only the front, then only the rear.","progression":"Start slow and build speed; then mix both brakes; then try different surfaces.","done_when":"You can stop at a marker without locking either wheel and know where each one starts to lock on that surface."},{"name":"Half-speed marker","how":"Ride one corner at about half speed, find a braking marker, then each lap brake a little later and get on the gas a little sooner.","progression":"Move the marker only after the current one is easy.","done_when":"Same marker and same entry speed lap after lap."},{"name":"Slow oval release","how":"Ride a slow oval and focus only on releasing the rear brake and putting the foot back on the peg at the transition to drive.","progression":"Raise speed once it is automatic.","done_when":"Foot comes off the pedal at the same spot every lap without thinking."},{"name":"Wheelie to stoppie control (intermediate and up)","how":"On flat, grippy ground at walking pace, lift the front slightly with throttle and clutch, bring it down with a tap of rear brake, then a small stoppie with front brake and weight forward, clutch in so it does not stall.","progression":"Only the height of the wheelie and stoppie grows with skill; keep both small.","done_when":"You can lift and set either wheel smoothly and stop the rear from rising by easing the front brake."}],"pro_tips":["Brake firmly, not gently: timid braking is a common time loss, but squeeze, do not grab.","Braking should flow straight into drive at the transition with no coasting in between.","On rocky or downhill braking use less front and more rear; avoid heavy front brake over loose rocks.","Keep a finger on the clutch while braking so a downshift or a stall-save is instant.","Advanced: a touch of trailing throttle while braking can settle the rear over high-speed braking bumps."],"coaches_differ":["Clutch while braking: Semics and Dirt Action keep the clutch out to use engine braking and say pulling it fully in removes it; MXA and the current skill pull it in for full braking without stalling, mainly on 125s and four-strokes in tight turns. Both agree on pulling it in at crawl speed.","Throttle while braking: Dirt Action calls trailing throttle an advanced bump technique in one article and lists leaving the throttle partly on as a panic mistake in another; MX-Gear says no clutch while braking. Treat trailing throttle as advanced only.","Rear brake in braking bumps: Semics allows light rear brake with light throttle in big bumps; Swap Moto (Clason) and the braking-bump tip say stay off the brakes and carry roll speed through them.","Weight while braking: Dirt Action and Josh Green say weight back; the current skill says hips back over the pegs, not on the fender. These fit if \"back\" means hips back while standing, not sitting on the rear.","Front/rear split: MXA gives about 70 percent front; the MXA drills article says the rear gives about 20 percent; exact numbers vary by surface and are rough guides only."]},"cornering_ruts":{"keys":["Enter with a small arc from slightly outside (a foot or two) rather than driving straight at the rut.","Lift the inside leg high and clear before leaning in, knee slightly bent, foot near the fork leg, toe angled so a touching boot slides instead of digging in.","Ball of the outside foot on the peg, outside knee pressing the bike; that keeps the tires pressed into the rut and stops the brake-side foot hitting the rear brake.","Use the throttle to correct lean in the rut: a little more if the bike is dropping too low or starting to lowside, a little less if it is standing up and climbing.","Choose the exit gear before entry; many coaches favour a taller gear with low revs so the bike lugs calmly through.","Read how far over to lean from how high other riders' tire marks sit on the rut wall; taller, firmer walls take more lean and need the leg higher.","Steady in, fast out: settle with the leg clear and eyes on the exit before applying power; slip the clutch a little on exit to drive hard without a wheelie.","Exit obstacles in the rut (roots, bumps): ease off before the rear reaches them, sit the bike up early, then get back on the power once it lands.","Off-camber ruts: slower, more patient entry, inside foot lower and flatter to help stabilise.","Engine braking on a four-stroke helps the front stay in a hard, rutted turn; on soft dirt less of it keeps the front from diving."],"faults":[{"fault":"Rear brake in the rut","looks_like":"Rear wheel hopping or popping out of the rut; bike standing up mid-turn.","why":"Using the rear brake while leaned over in the rut.","fix":"Finish braking before the rut; if needed, a light front brake drag keeps the front planted.","drill":"Rut circles with no rear brake."},{"fault":"Choppy throttle in the rut","looks_like":"Bike rising and dropping in the rut, rider correcting with the bars.","why":"On-off throttle bursts.","fix":"Hold a steady throttle and adjust it only to correct the lean.","drill":"Throttle trailing laps through one rut."},{"fault":"Front tucks when backing off","looks_like":"Front knifes into the rut after the rider rolls off mid-rut.","why":"Closing the throttle mid-rut adds engine braking and loads the front.","fix":"Keep a little throttle on; use a touch of clutch to keep moving rather than backing off."},{"fault":"Too little momentum","looks_like":"Rider standing up or dabbing mid-rut, bike stalling or falling in.","why":"Over-braking before the rut and then trying to build speed in it.","fix":"Enter with enough speed to carry through; set throttle while braking so entry needs no big change.","drill":"Start on short, shallow ruts and move to longer, deeper ones."},{"fault":"Leaning with no pressure on the pegs","looks_like":"Rider and bike leaned together, tires skating, little control if it slips.","why":"Weight on the seat and inside, not on the outside peg.","fix":"Weight the outside peg and outside knee so the tires stay pressed into the rut."},{"fault":"Dabbing the inside foot","looks_like":"Inside boot touching down repeatedly, front tucking.","why":"Habit or nerves.","fix":"Keep the inside leg up and leading; only dab when you truly need balance."},{"fault":"Hitting roots with the front leaned over","looks_like":"Front pushed wide or tucked at the rut exit.","why":"Crossing a root while still leaned.","fix":"Sit the bike up before the obstacle, coast over angled roots with the front light."}],"drills":[{"name":"Throttle trailing","how":"Ride a single rut repeatedly holding a smooth, steady throttle; change it only to fix lean.","progression":"Shallow rut first, then deeper, then longer.","done_when":"The bike stays at a steady height in the rut and exits without a bar correction."},{"name":"Gear call","how":"Before each rut, say the entry and exit gear and check them on the approach.","progression":"Try one gear taller than usual.","done_when":"No shift needed in or right after the rut."},{"name":"Rut circles","how":"Ride circles in a rutted turn without the rear brake; drag the front lightly if sliding out. Do it with one leg forward, then both feet on the pegs, then standing.","progression":"Small then big circles; move through the three stances.","done_when":"Smooth circles in each stance without the rear brake."},{"name":"Rut track no brakes, no clutch","how":"Ride a short rut track with laps that use no brakes and laps that use no clutch.","progression":"Slow to feel the flow, then build pace.","done_when":"You can lap it at a steady pace without either control."}],"pro_tips":["Look at the exit as soon as you are in the entry, not at the front fender; the bike follows the eyes.","Keep the head over the front third of the bike; falling back over the rear is the classic rut mistake.","Accept a little mid-turn speed for a cleaner exit in technical ruts.","Practise ruts instead of avoiding them; they get easier only with reps.","Where ruts cross at the exit, keep the front light with a little power and set it down where it does not break your flow."],"coaches_differ":["Sit or stand into the rut: MXA says stay standing as long as you can; ADB and Dirt Action sit early (a few metres before) with the leg up. The current skill says sit forward.","Lean the body or not: Racer X and Dirt Action lean head and upper body into the turn with the bike; Keegan says tilt the bike under you rather than leaning with it; BCP says match the bike angle in ruts and berms. Upper body stays over the bike in all of them.","Brakes in the rut: the current skill says brake before the rut, not in it; MXA (advanced), Keegan and Damian Smith allow a light front brake drag through the first part of tight ruts. All agree no rear brake in the rut.","Gear: MXA and ADB favour a taller gear lugging; Keegan only says choose the exit gear beforehand."]},"cornering_flat":{"keys":["Brake hard standing and in a straight line, then move from standing to seated in one smooth motion as you release the brakes; drop onto the seat gently, not with a thump.","Some coaches release the rear first but keep a little front brake as you sit to settle the front, then come off it before the lean.","Enter wide, cut to the inside at the apex and let momentum carry you out wide on exit.","Sit on the outside edge of the seat and press the outside peg with the ball of the foot, toes down; keep the upper body upright over the bike.","Light on the bars: a tense grip makes the front push; relaxed arms let the bike drift safely.","Throttle comes in gently from about mid-corner; steady throttle turns the bike better than brake.","On exit pick the bike up, move back on the seat for rear grip and build to full throttle smoothly.","Hardpack sweepers: a small controlled drift is fast; a big sideways slide is not."],"faults":[{"fault":"Front pushes from a tight grip","looks_like":"Front tire scrubbing wide, rider stiff with elbows locked.","why":"Tension on the bars and too much entry speed.","fix":"Relax the grip, slow entry slightly, weight the outside peg."},{"fault":"Braking in the turn instead of before","looks_like":"Front tucks right at turn-in.","why":"Still on the brakes while leaning.","fix":"Finish braking upright, then lean."},{"fault":"Dropping hard onto the seat","looks_like":"Bike jolts or wiggles as the rider sits.","why":"Abrupt sit-down unloading and reloading the tires.","fix":"Sit in one smooth move as the brakes come off."},{"fault":"Rear spins on exit from clutch feathering","looks_like":"Rear spinning, bike slow despite noise.","why":"Feathering the clutch on exit so the tire breaks loose.","fix":"Roll the throttle on smoothly at the edge of grip; use less clutch."}],"drills":[{"name":"Cone turn track","how":"Set a cone on flat ground and ride laps around it practising the stand-to-sit transition and where to look.","progression":"Tighter radius, then figure eights, then both directions.","done_when":"Smooth stand-to-sit at the same spot every lap with the eyes on the exit."},{"name":"50, 75, 90","how":"Ride the same flat corner at about half, three-quarter and near race pace in turn.","progression":"Move up a step only when the slower one is clean.","done_when":"Race pace looks like the 50 percent version, just faster."},{"name":"Powerslide circles (once grip is solid)","how":"On a flat, open, smooth area, slide the rear around a circle using seated body position and measured throttle.","progression":"Seated first, then standing with both feet on the pegs.","done_when":"You can hold a small slide and stop it with the throttle at will."}],"pro_tips":["Flat turns are not a rest spot; more speed makes the front push harder, so stay smooth and patient on the gas.","Watch other riders' lines in flat turns, and decide your line early as bumps build."],"coaches_differ":["Clutch on exit: Shane Watts says do not feather it, it spins the rear; Sean Hamblin says feather it to control traction rather than dumping it.","Upper body: Hamblin leans the upper body back a little to balance weight; Sleeter leans the head forward over the bars; the current skill keeps the body upright.","Inside foot: most keep it up and forward; Childress (hardpack/Baja style) lets it skim the ground for balance."]},"cornering_off_camber":{"keys":["Slow more than for a normal corner and brake a bit earlier; gravity pulls you down the slope. Use a light touch on both brakes, and especially little rear.","Carry rolling speed in, so the rear does not drop away when you get back on the gas.","Sit or crouch toward the outside (downhill) side, upper body upright and level; load the downhill peg as hard as you can and let the bike lean beneath you.","Wait longer than usual for the throttle, then hold it steady; on-off throttle makes the tires slip downhill.","Look ahead at a point on the far side or the top, not at the ground in front.","If there is a rut, aim for its inside edge on entry so the rear does not miss it, and accelerate only once both wheels are in it.","Off-camber uphill: keep the front light and aimed slightly uphill of the main line so the rear stays out of the loose dirt on the downhill side."],"faults":[{"fault":"Looking down at the slope","looks_like":"Bike standing up and drifting down the hill.","why":"Eyes on the ground just ahead.","fix":"Pick a target on the far side and keep the eyes on it."},{"fault":"Early throttle on an off-camber","looks_like":"Rear steps out downhill on exit.","why":"Getting on the gas at the usual point.","fix":"Wait longer, then roll on steadily."},{"fault":"Too much rear brake on an off-camber","looks_like":"Rear sliding downhill on entry.","why":"Rear brake used as on a flat turn.","fix":"Brake earlier and lighter, mostly front, upright."}],"pro_tips":["A slower entry that stays locked into the rut beats a fast one that slides off the camber."],"coaches_differ":["Seat or crouch: Andrew Short and Nathan Woods sit toward the downhill side; Shane Watts crouches and stays centered front to back while loading the downhill peg so hard the inside foot may lift."]},"berms":{"keys":["Lean with the bike in a berm (unlike a flat turn); shoulders over hips, bend at the core rather than folding forward at the hips.","Release the brakes and sit with the leg out a little earlier than feels natural: it carries more speed, gives time to set up and allows a taller gear.","Start the roll-on a little before the point where you would go full throttle, and keep weight forward as you open it.","Do not hit the apex too early: turn in, then straighten so you can get on the gas sooner.","Keep weight low and centered; weight carried high pushes the bike up the berm and delays the exit.","If the bike starts to stand up or climb the berm, quick nips of the clutch cut drive faster than the throttle.","Squaring a berm: you do not have to ride the whole thing; turn sharply off it, point the bike, stand it up and drive. Useful to pass or avoid a hole.","Landing into a turn: decide berm or inside before the jump; the berm is longer but easier to carry speed through, the inside is shorter and harder."],"faults":[{"fault":"Braking late then grabbing throttle and clutch mid-berm","looks_like":"Bike lurches or stands up halfway round.","why":"Still braking at turn-in, then trying to make up speed in the turn.","fix":"Sit and release the brakes earlier, then roll on early and smoothly."},{"fault":"Folding forward at the hips","looks_like":"Head low over the bars, back rounded, weight too far forward.","why":"Bending at the hips instead of the core.","fix":"Shoulders over hips, bend through the core."},{"fault":"Locked stiff inside leg","looks_like":"Inside leg straight and rigid, boot catching the berm face.","why":"Bracing with the leg.","fix":"Slight knee bend, toe pointed so the sole runs parallel to the ground and slides if it touches."},{"fault":"Under-leaning and leaning the body out","looks_like":"Bike too upright, rider hanging the upper body outward.","why":"Not trusting the berm.","fix":"Lean the bike more and keep the body with it."}],"drills":[{"name":"Ten clean in a row","how":"Pick one berm and ride it until you nail it ten times in a row; any mistake restarts the count.","progression":"Then push the entry a little faster with a safe runoff.","done_when":"Ten consecutive clean laps of that berm."},{"name":"Many reps of one turn","how":"Repeat the same forgiving berm 30 to 50 times, pushing slightly each time: enter a bit faster, hold the line longer, brake later.","progression":"Only on a turn with safe runoff.","done_when":"You know where the edge is without crashing."}],"pro_tips":["Get on the power sooner, not harder.","Coming off the berm, let the bike drift toward the outside on exit.","If an inside line off a jump goes wrong, run wide to the berm early, even just its end, rather than forcing it."],"coaches_differ":["Entry: MX-Gear (credited to Catanzaro) says either come off the rear brake and coast in, or brake to the transition and get straight on the gas, and to try both; Racer X Corners and Semics say no coasting at the transition."]},"race_lines":{"keys":["Tight 180s: come in from the outside, cut to the inside and let the bike run wide on exit, a U shape.","Off a jump into a turn the line is fixed in the air: choose it before the face.","Plan a corner several moves ahead and decide your approach before you reach it.","Use the full track width to slow down; drifting wide out of one turn can close the entry to the next.","Pick lines around loose rocks and the trough where they collect, especially on downhills."],"faults":[{"fault":"Butchering the corner after a jump","looks_like":"Good jump, then over-braking or running wide into the next turn.","why":"All attention on the jump, none on the turn.","fix":"Choose the turn line before the jump and spot the landing early."},{"fault":"Entry too tight","looks_like":"Rider turns in early and has to stop mid-turn.","why":"Cutting the entry for the shortest line.","fix":"Enter wider, use the track width, and aim for a better exit."}],"pro_tips":["Try lines you are not used to in practice; fast riders keep testing."]},"corner_body_position":{"keys":["Load the outside peg from turn-in to exit: release the rear brake, press through the leg and the ball of the foot, toes angled in, and keep pressure through the exit.","Brace the outside knee against the tank to load the peg; do not prop yourself up on a straight, locked leg.","Outside peg pressure matters most on hardpack (rear bite), in ruts (stability), over acceleration bumps (keeps you from bouncing off the seat) and at higher speed.","Rotate through the hips rather than rounding the back; it gives more leverage on the pegs.","Ride on the balls of the feet with toes pointing in so the knees can grip.","Seat position moves with the job: forward to turn and for front grip, a little back when the rear may spin under hard drive.","Weight shifts with the controls: braking pushes weight forward, so move back; accelerating pushes it back, so move forward.","Initiate the turn with the outside shoulder and elbow (Ryan Hughes video title; detail not readable).","Keep the fingers resting on the clutch and front brake, not all four on the grip, especially in a pack."],"faults":[{"fault":"Both feet off the pegs","looks_like":"Both boots off the pegs mid-corner, bike skating.","why":"Nerves, or no outside peg habit.","fix":"Keep the outside foot loaded on the peg; only the inside foot comes off.","drill":"Laps with both feet on the pegs through every corner."},{"fault":"Sitting heavy and bouncing","looks_like":"Rider thrown up off the seat over exit chop.","why":"Weight on the seat, not the pegs.","fix":"Push weight into the outside peg and grip with the knees."},{"fault":"Sitting too far back in turns","looks_like":"Rider mid-seat or behind, front pushing.","why":"Habit, or reacting to the bike.","fix":"Sit an inch or two farther forward and get more weight over the bike.","drill":"Note where you sit in practice and move forward an inch or two."},{"fault":"Toes out, knees off the bike","looks_like":"Gap between knees and bike, toes splayed.","why":"Feet turned out so the knees cannot close.","fix":"Turn the toes in; the knees then grip the tank.","drill":"Knee-grip test standing off the bike."}],"drills":[{"name":"Outside peg laps","how":"On a track you know, ride laps focusing only on loading the outside peg in every corner.","progression":"Then laps keeping both feet on the pegs to feel the difference.","done_when":"Outside foot never comes off the peg and you feel the rear bite on exit."},{"name":"Knee-grip test","how":"Stand with feet peg-width apart, toes out, try to touch your knees; then turn the toes in and try again.","progression":"Carry the toes-in feel onto the bike.","done_when":"Knees reach the tank easily with toes in."},{"name":"Full standing lap","how":"After standing circle drills, ride a whole lap standing.","progression":"Stand through rough chop and transitions first.","done_when":"A full lap standing without the arms tiring."}],"pro_tips":["Sharp pegs and broken-in boots make outside-peg weighting easier to hold.","Lean the bike about half of the direction change (a 90-degree turn, roughly 45 degrees lean) as a rough rule; much more or less risks a low-side or high-side."],"coaches_differ":["Seat position: most say sit far forward; Racer X Braking and Set-Up notes sitting too far forward on the tank removes rear grip, and Jason Thomas moves back when the rear may spin under hard drive."]},"throttle_clutch_traction":{"keys":["Light to moderate drive helps the front steer and stay planted; heavy drive starts a slide that makes the front countersteer.","On exit, squeeze the clutch in slightly, then feed it out as you roll on to meter power to the rear.","Quick nips of the clutch cut drive faster and more precisely than the throttle when the bike is about to stand up or climb out.","Aim for enough power to drive out without wheelspin, swapping or a wheelie; each costs momentum.","Keep a finger on the front brake when getting on the gas hard; a light touch keeps the front down.","In a rut with the front light, stay on the power and modulate the clutch to hold traction."],"faults":[{"fault":"Hammering throttle and clutch","looks_like":"Loud, roosting exit that is not actually fast.","why":"Feeling of speed from noise and spin.","fix":"Get on the gas earlier but smoother."},{"fault":"Clutch as a crutch","looks_like":"Lever pulled in at every exit to settle the bike, then let out.","why":"Habit; covering mistakes with the clutch.","fix":"Control the exit with throttle and body; ride sessions without the clutch.","drill":"No-clutch laps."},{"fault":"Grabbing too much throttle out of a turn","looks_like":"Bike shoots wide across the track on exit.","why":"Big throttle before the bike is upright.","fix":"Roll on progressively as the bike comes up."}],"drills":[{"name":"No-clutch laps","how":"Ride laps without using the clutch except to stop.","progression":"Then laps without the rear brake; then both.","done_when":"You keep flow through the lap without stalling or bogging."}],"pro_tips":["On a four-stroke the clutch is mostly unnecessary if the corner is done right; keep a finger on it for small corrections.","Apply throttle by how much traction you feel once the bike is planted in the corner."],"coaches_differ":["How much clutch: Gary Bailey, Shane Booth and Racer X Corners use clutch on exit to meter drive; Andy Bowyer, MX-Gear and Cade Clason say use it as little as possible on a four-stroke; Shane Watts says feathering on flat-turn exits spins the rear."]},"jumps":{"keys":["Two ways to leave a face: launch (push down into the face with the legs, then spring up as the bike rebounds) for height and distance, or absorb (let the bike rise into bent knees and elbows) to stay low over jumps you would otherwise overjump. Pick by what the landing needs.","Before a new jump, picture how the face will throw the bike (height and distance) and decide the speed from that; speed alone is only part of the answer, the face technique matters as much.","Keep the body steady front to back from face to air; leaning forward or back at the lip changes the bike's pitch.","Landing into a turn: choose the turn line (inside or berm) before takeoff, because you cannot change it in the air. Eyes on the landing, then up to the line.","After a downside landing into a turn, stay standing while braking; brake lightly at first and add front brake only once the front is loaded; sit when the bike is settled and slow enough.","Pulling the bars up hard on a face lifts the front too high and makes the jump harder to clear; lift with the legs, not a yank."],"faults":[{"fault":"Coming up short off a big jump","looks_like":"Rear wheel hits the landing face or lip; rider's feet bounce off the pegs on impact.","why":"Approach speed slightly short or the face was ridden passively; on big jumps there is little margin.","fix":"On doubles and gaps do not creep up; follow a rider who clears it at a known speed or roll it. On tabletops add face technique (load and spring) before adding speed.","drill":"Tabletop only: jump to a marker on the top, then move the marker a little further each set once you hit the current one three times running."},{"fault":"Cruising off the lip (no height)","looks_like":"Bike barely leaves the face, flat trajectory, lands short on a tabletop even at decent speed.","why":"Rider just rides up the face without loading the suspension, or absorbs when the jump needs a launch.","fix":"Push down with the legs going up the face and stand tall at the lip as the suspension rebounds, like a bicycle bunny hop.","drill":"Alternate one absorb jump and one launch jump on the same small tabletop to feel the difference."},{"fault":"Panic on a landing into a turn","looks_like":"Rider drops to the seat on landing, stabs the rear brake, or shoots past the turn.","why":"Line not chosen before takeoff; jump distance wrong (too short bounces off the down ramp, too long overshoots).","fix":"Decide the line before the face; land standing; light brakes then progressive front; if the inside goes wrong, commit early to the berm."},{"fault":"Grabbing throttle out of a turn before a jump","looks_like":"Bike squirts sideways or into the next lane on the face of a jump that follows a corner.","why":"A handful of throttle mid-exit breaks traction just before the face.","fix":"One smooth, steady roll-on from exit to face."}],"drills":[{"name":"Launch vs absorb on one tabletop","how":"On a small tabletop you already clear easily, alternate a launch jump (load and spring) and an absorb jump (soak the face) at the same speed.","progression":"Same speed throughout; only once both feel controlled, use the absorb version on a roller where you would otherwise overjump.","done_when":"Ten in a row where you can tell the two apart and land balanced each time."},{"name":"Landing target","how":"Put a visible marker (cone placed off the line by a helper, or a fixed mark) on a tabletop landing; look at it in the air and aim the front wheel at it.","progression":"Move the marker shorter and longer in small steps, tabletops only.","done_when":"You land within about a bike length of the marker on most attempts."},{"name":"Quiet landings (off the bike)","how":"Jump on the spot and land as quietly as possible, using ankles, knees and hips as suspension.","progression":"Then apply the same soft legs to small tabletop landings, landing on the balls of the feet.","done_when":"Landings on the bike feel soft and the bike settles straight away."}],"pro_tips":["Seat-bouncing a big jump (Zach Osborne style) can add distance, but coaches call it not ideal; treat it as advanced and only out of a slow corner where there is no other way.","Land on the balls of the feet, not the arches, on normal landings: more ankle travel and control.","Off the throttle as you come into the landing, then back on once the bike settles."],"coaches_differ":["Sighting-lap jumping: Swap Moto Live advises not to roll jumps in early laps and to jump tabletops part way first; BAK's base coaching rightly warns that creeping up on doubles and gaps lands you on the lip. Reconcile: partial jumping is for tabletops only.","Landing attitude: Dirt Action suggests landing slightly front-first when landing into a turn so the front brake can be used; Racer X says in deep mud land rear-first with the throttle on. Both are context-specific (downside into a corner vs. mud)."]},"scrubbing":{"keys":["Scrub toward the direction the track turns next (into a left-hander, lay it toward the left).","Do not scrub jumps you must accelerate hard to clear, or on very fast straights; scrubbing sheds distance.","Approach the face at only a slight angle; steep angles up the face are elite-level.","Lean the bike before the lip; how far depends on face steepness and ruts. Ruts in the face make it hard to get sideways.","Keep the inside foot on the peg so the toe cannot catch; tuck the outside knee and elbow, steer the bike with arms and legs while head and torso stay neutral.","Straighten the bars before the front touches down so the front wheel does not catch; aim the bike at the next corner and get back on the throttle or brakes, not coasting."],"faults":[{"fault":"Over-leaning on the face","looks_like":"Rear steps out on the face, bike lands still leaned, rider bails or highsides.","why":"Too much lean too early for the traction available on the face.","fix":"Less lean, start at normal jump speed, add lean only as it stays repeatable.","drill":"Small tabletop, a few degrees of lean, straighten early."},{"fault":"Toe catch on takeoff","looks_like":"Inside foot off the peg or dangling at the lip; leg dragged back.","why":"Rider lifts the inside foot thinking it helps the lean.","fix":"Inside foot stays on the peg; it is the outside foot and knee that tuck."},{"fault":"Landing with bars still turned","looks_like":"Front wheel crossed up at touchdown, bike tucks or deflects.","why":"Straightened too late.","fix":"Turn the bars back and straighten earlier; reduce the scrub until timing is consistent."},{"fault":"Scrub that will not happen","looks_like":"Bike goes up the face straight despite the rider leaning.","why":"Blipping the throttle on the face, poor knee grip, steering with the upper body.","fix":"Steady approach, squeeze with the knees, use legs and arms rather than the torso."}],"drills":[{"name":"Coasting tabletop","how":"On a small tabletop you clear easily, practise going off the face without blipping the throttle to learn how the bike behaves with engine braking.","progression":"Then add a slight lean at the same speed; only later, a little more speed so you clear the table while scrubbing.","done_when":"You land straight on the downside every time with a small scrub angle."},{"name":"Small-jump scrub ladder","how":"Start on the smallest jump you jump consistently; small angle, straighten early.","progression":"Increase angle first, then speed, then jump size; never on a jump you are not already clearing comfortably.","done_when":"Repeatable, straight landings at each step before moving up."}],"pro_tips":["A scrub is an overjump-prevention tool: come in with more speed than the jump needs and scrub to shorten it, keeping speed into the landing.","Turning on the face of a jump to shed speed before whoops (as Tomac does) is very advanced and not for home practice."],"coaches_differ":["Throttle during the scrub: Racer X 'Motocross 101' says a scrub only works fully off the throttle; BAK's base coaching currently says keep the throttle on. Australasian Dirt Bike has the rider brake and compress before the face. Recommend BAK revise to: steady on the approach, no blips on the face, the bike typically scrubs off the throttle; back on the gas for the landing."]},"whoops":{"keys":["Gear one higher than feels natural: the rear drives instead of spinning and the bike stays more stable.","Weight toward the rear but not so far back that the front misses the tops; head over the bars, elbows high, feet back on the pegs.","Squeeze hard with the legs to keep the bike straight; that saves the upper body.","Dry whoops: carry speed but do not over-rev, or the rear spins. Tacky or soft whoops: manage the throttle; jumping may suit them better.","Choose the line through the whoops that links best to the next section.","On the exit move forward for drive and expect some wheelspin.","Skimming is committing: hesitation on entry or mid-set is what causes the big crashes. If you are not committed, roll them.","Irregular whoops: pick the smoothest line, use a bigger bump to loft the front over smaller ones, and treat square-edged bumps with more caution than round ones."],"faults":[{"fault":"Switching style mid-section","looks_like":"Rider starts skimming, then tries to jump (or the reverse) and lands in a trough.","why":"Indecision, or the whoops were not suited to the chosen style.","fix":"Decide before entry; if unsure, roll through at a speed you control."},{"fault":"Jumping whoops that are not ready","looks_like":"Bike catches the sharp edge of a fresh or rebuilt whoop and kicks.","why":"Fresh whoops have abrupt transitions that do not allow a consistent jumping speed.","fix":"Skim or roll fresh whoops; jumping works better once they are worn in and smoother."},{"fault":"Wheels dropping into the bottoms","looks_like":"Suspension bottoming in each trough, rhythm lost, front tucking.","why":"Too slow to skim, weight forward, or lost rhythm.","fix":"Hips back, steady throttle, higher gear; build speed gradually and roll them if you cannot stay on top yet."}],"drills":[{"name":"Whoop speed ladder","how":"On a short set of small, rounded whoops, ride standing with hips back, legs squeezing, one gear high.","progression":"Start slow and roll them; add a little speed each pass only while the bike tracks straight.","done_when":"The rear tracks straight, the front stays on the tops, and you feel less effort than rolling."},{"name":"Sand whoops in a turn: front lofting","how":"Standing, both feet on the pegs, lean with the bike and loft the front wheel from top to top with a touch of clutch and throttle.","progression":"Small sand turns first; keep the loft low so the front does not drop into the next hole.","done_when":"The bike does not stand up mid-turn and the front stays light."}],"pro_tips":["Pros say you learn whoops mostly in races because practice time on them is limited; know your own and the bike's limit.","Whoops are a passing place: a faster line through them can set up a pass in the next turn.","Jumpers have to slow to find jumping speed; blitzers can pass them, so jumping is the consistent option, skimming the fast one."],"coaches_differ":["Skim or jump by condition: Vialle skims fresh or very dry whoops and jumps when they are breaking down but still grippy; WSX says jump when they are breaking down or very tacky; Racer X warns against jumping fresh, abrupt whoops. Consistent theme: condition decides, not preference.","How far back: Dubach says weight to the back; Vialle and Dirt Action warn not so far back the front misses tops or rises too high."]},"rhythm":{"keys":["Pick a combination you can repeat every lap for the whole race; a line that works once in qualifying may fall apart with fatigue.","Bigger combos usually save time, but not if you must nearly stop in the corner before to make them; compare what you gain on the jump against what you lose in the turn.","Out of a corner, the simplest combo (often double-double-double) is the safe base; single-double-triple is quicker but more technical.","Absorb the first jump and push the bike down into the face of the next to carry speed; then look at the landing of the last jump.","Squeeze the bike with feet and knees; your legs do the work, not your upper body.","Triples: entry speed comes from the corner before, so set up that corner first."],"faults":[{"fault":"Overjumping the second or third jump","looks_like":"Bike flies past the landing of a combo and lands flat or on the next face.","why":"Not absorbing the first jump, so too much speed carries through.","fix":"Soak the first jump, push into the next face, eyes on the final landing."},{"fault":"Muscling the rhythm with the arms","looks_like":"Stiff arms, elbows locked, bike kicking off peaked faces.","why":"Upper body doing the work, landing on the arches.","fix":"Legs extend like a trampoline from bent to straight, balls of the feet, light hands."},{"fault":"Chasing the big combo out of a broken corner","looks_like":"Rider nearly stops in the turn to make a triple and loses time to riders taking a smaller line.","why":"Corner before the section has broken down.","fix":"Take the smaller line and attack the corner instead; recheck as the track changes."}],"drills":[{"name":"Rhythm by pieces","how":"On a safe section of round rollers, ride the simplest combo (doubles) until it is smooth, absorbing and pushing each face.","progression":"Only add the next combination when the current one is repeatable for a full practice moto, not one lap.","done_when":"Same landing spot lap after lap with legs, not arms, doing the work."}],"pro_tips":["'Corners are for dough, jumps are for show': often the time is in the corner before the rhythm, not in the bigger jump.","Peaked rhythm jumps punish mistimed riders more than round ones; practise timing on rounder sections first."]},"sand":{"keys":["A little throttle almost the whole lap: losing speed lets the weight come forward and the front bury.","Wide, round lines and large arcs; squaring off corners digs a trench and kills speed.","Let the sand slow you into a corner instead of stabbing into it; brake gradually.","Shift with a touch of clutch and stay on the throttle; letting off to shift bleeds speed.","In berms stay low, where the sand is usually firmest.","Look further ahead than usual and remember how each section looked last lap; sand lines change every lap.","Keep feet on the pegs; a dabbed foot drags in sand and upsets balance.","Ride loose but grip with the knees; you cannot ride stiff in sand."],"faults":[{"fault":"Front knifing while standing","looks_like":"Front tire digs and turns in, rider pitched over the bars.","why":"Leaning too far forward when standing, or rolling off.","fix":"Weight back, keep the front light, stay on the throttle."},{"fault":"Bogging the rut","looks_like":"Bike sinks mid-corner, rear spinning, roost but little drive.","why":"Turning too sharply, rushing the entry, too low a gear.","fix":"Wider radius, set up patiently, gear higher with a finger on the clutch."},{"fault":"Wheelie on a sand exit","looks_like":"Front lifts as the rider drives out of a sand turn.","why":"Too much throttle with weight back.","fix":"Slip the clutch a little and lean forward for the exit."}],"drills":[{"name":"Big-arc sand turn","how":"In one sand corner, ride a wide round arc a gear higher than usual, staying on a light throttle from entry to exit with feet on the pegs.","progression":"Tighten the arc a little each set only while the bike keeps driving.","done_when":"No dabbing and no bogging for a full set of laps."}],"pro_tips":["Standing a lot in sand loads the lower back; a kidney belt helps some riders.","In sand berms keep the body neutral and the inside leg toward the middle of the bike to put weight on the rear tire."],"coaches_differ":["Body position: Cade Clason says lean further back for drive; Dirt Action's sand-turn tip has the rider seated at the front of the seat, head over the bars, in turns. Reconcile as in BAK's base coaching: back to drive on straights and through whoops, forward to turn.","Rear brake: Dirt Action says the rear brake works better in sand; Clason says use less of it for smoother control.","Inside foot: Clason says no dabbing; Dirt Action keeps the inside leg out with the toe pointed so it slides rather than digs. Both agree the foot must not plant."]},"mud":{"keys":["Lean the bike less in mud; normal cornering lean makes it slide out.","Keep the head back (not over the bar pad) so legs stay high and the front stays light.","Keep momentum to slip the clutch less; mud heats and wears the clutch.","Most mud corner crashes happen between halfway and three-quarters through the turn where the line breaks down; enter slower and do not gas too hard too soon.","Feet: in sandy mud dragging a foot for balance can work; in thick clay keep feet up, the clay grabs boots.","Avoid deep standing water; it can stall the bike and hide holes.","Ride loose and expect the bike to move by itself; a tight grip tires you and upsets balance.","Vision decides mud races: a start near the front matters more than usual because roost blinds riders behind."],"faults":[{"fault":"Front-first landing in mud","looks_like":"Front plants and bars twist on landing.","why":"Nose-low attitude in the air.","fix":"Land rear-first with the throttle on in deep mud."},{"fault":"Riding the mud tight","looks_like":"Elbows locked, white knuckles, rider fighting every slide.","why":"Fear of the bike moving under them.","fix":"Softer grip, knees on the bike, let it move."},{"fault":"Losing vision","looks_like":"Rider pulls goggles off early, rides blind or slows sharply mid-race.","why":"No goggle plan: no tear-offs or roll-offs, no fresh pairs.","fix":"Fresh prepared goggles each moto, tear-offs or roll-offs, a visor extension; wipe rag tucked in the pants."}],"pro_tips":["Mud evens the field; a positive attitude before the start is part of the job.","Prep: foam in mud traps, silicone under fenders, radiator mesh in severe mud, spare boots and helmet; wash the bike between motos so it cools.","Coolant puking from the overflow means hot but still full; worry when the steaming stops."],"coaches_differ":["Gear choice: BAK's base coaching and most race sources favour a higher gear and momentum; MX247's coaching page says low gears for traction and to avoid stalling. Low gears may suit slow, sticky trail mud; race sources favour taller gears.","Braking: MX247 says ease off the throttle rather than brake; others simply say avoid sudden braking."]},"hardpack":{"keys":["Approach on the gentlest radius and pivot near the middle of the corner; a wider line carries speed on slick dirt.","Keep the time rolling (off brakes, off gas) short; release the brakes at the pivot point and get to the throttle.","Sit forward and slide toward the outside of the seat to press the tires into the ground; weight the outside peg.","If the rear starts to slide on exit, hold the throttle steady rather than snapping it shut; backing off mid-slide raises highside risk.","In wet hardpack avoid the apex where water collects.","On a hard, slick track the inside often has no grip, so lines move to the berms; passing gets harder, so starts matter more.","Crashes hurt more on hardpack; ride a margin below your limit."],"faults":[{"fault":"Snapping the throttle shut mid-slide","looks_like":"Rear steps out, rider rolls off, rear suddenly grips and bucks the bike.","why":"Instinct to back off on a slide.","fix":"Hold the throttle steady and let the rear come back; use a taller gear so slides are gentler."},{"fault":"Entering in too low a gear","looks_like":"Wheelspin the moment the throttle opens.","why":"Too much torque at the rear tire for the grip.","fix":"One gear higher, smooth roll-on."}],"drills":[{"name":"Pivot-point corner","how":"Pick one slick flat corner, mark a pivot point near the middle, brake smoothly to it, release, and roll on from there.","progression":"Move the braking a little later only while the front never pushes.","done_when":"Consistent exits with no wheelspin roost."}],"pro_tips":["On hardpack a holeshot device that pulls the front down also reduces rear grip; balance wheelie against wheelspin.","Experiment with dropping tire pressure a pound or two within maker range and compare."]},"hills":{"keys":["Look at the hill before riding it; build most speed before the slope starts, and on technical climbs keep the wheels turning.","Technical climb: short bursts of throttle before holes, rocks and ruts to carry over them, easing between so the rear does not break loose.","Ease off before a blind crest: you cannot see what is beyond.","Lean forward as the climb steepens, but not so far that the rear spins.","Downhill: low gear chosen before the top, start slow, keep the rear wheel behind the front; pulse the rear brake rather than locking it.","Downhill: on bumpy descents with few ruts a slight diagonal line hits bumps at an angle and kicks the bike less; watch speed into g-outs.","Off-camber hillsides: weight the downhill peg, steady throttle, eyes on a spot across the camber, fingers on clutch and brake."],"faults":[{"fault":"Stopping in a spot with no restart","looks_like":"Rider stalls mid-steep slope and cannot turn or restart.","why":"Pushed on past the point of doubt.","fix":"If you doubt the climb, stop early on a flatter, stable spot; think about what went wrong before trying again."},{"fault":"Too fast into a g-out on a descent","looks_like":"Suspension bottoms hard at the bottom, rider thrown forward, feet off the pegs.","why":"Speed builds fast downhill; coasting with weak leg grip.","fix":"Control speed early, squeeze with the legs, weight slightly back."},{"fault":"Bike gets sideways downhill","looks_like":"Rear swings out, bike slides across the slope.","why":"Locked rear brake.","fix":"Pulse the rear, progressive front, rear wheel tracking behind the front."}],"pro_tips":["Over-revving a two-stroke on long descents can foul the plug; a hot four-stroke can be hard to restart after a failed climb.","On descents stay in a gear you are comfortable with: too low a gear binds the chassis when the clutch is released, too high bogs."],"coaches_differ":["Throttle on climbs: Sam King (trials coach) eases the throttle while climbing and uses bursts at obstacles; Transmoto says on straight, wide climbs keep accelerating. Context: technical vs open climbs.","Failed climb recovery: Sam King turns the bike 90 degrees across the slope with a foot on the high side; Transmoto (and BAK's base coaching) stall it, hold the brake and get off on the uphill side to turn it. Both work in different terrain; BAK should not present one as the only way.","Climb body position: Transmoto says sit over the rear for traction on climbs and shift forward when the front lifts; BAK's base coaching says stand with weight forward. Depends on steepness and grip."]},"passing":{"keys":["Block pass: commit before halfway through the turn; later than that and you are too committed to change line.","Whoops and rough sections are places to set up a pass: a faster line there gives the drive to pass in the next turn.","When leading by a margin, ride what is needed; extra risk earns no extra points."],"pro_tips":["Running wide in a turn invites a rider underneath; hit your marks."]},"race_starts_first_turn":{"keys":["A poor gate pick is not fatal: a clean start and committed throttle from an outside gate can still win.","On many start straights a middle gate is about as good as any; a single-digit pick is no guarantee.","Decide the start strategy and the lines for the first laps before reaching the line; stay committed but adapt.","In turn 1, inside riders must avoid being hit from behind; outside riders who run wide get cut under."],"drills":[{"name":"First-person start rehearsal","how":"Before the moto, mentally rehearse the gate drop, the first shifts and the line into turn 1 from your own viewpoint.","progression":"Do it before practice starts too, so it becomes part of the routine.","done_when":"You react to the gate without thinking about the steps."}],"coaches_differ":["Inside vs other gates: Matt Walker calls the inside safer and the outside risky, especially on short supercross starts; the Loretta Lynn's story shows outside gates winning and the middle being just as good on that straight; BAK's base coaching says pick by dirt and line. Track-specific."]},"race_day":{"keys":["Track walk: note hazards near the line (trees, rocks), soft spots and filled holes that will reappear as bumps, how each face will launch you and what is after each landing.","Practice pace in stages: moderate for the first laps, harder in the middle, full pace only at the end.","Tabletops in early laps: jump part way, then further; never creep up on doubles (see jumps).","Sometimes give up speed in one place (brake earlier, roll off, shorten a jump) to hit the next section right; choose the approach you can repeat every lap.","On a fresh track, help form the lines early by riding them consistently."],"faults":[{"fault":"Wide open from lap one","looks_like":"Mistakes and near-misses in the first practice laps on a new track.","why":"Treating practice as a time trial before learning the dirt.","fix":"Staged pace: moderate, then harder, then full."}],"pro_tips":["Practise on varied tracks and in varied conditions, and ride full race-length motos, not just a few hot laps."]},"mental_game":{"keys":["Expect nerves: even experienced pros feel them on the line.","Slow, deliberate breaths while staged; then narrow focus to one cue at a time: the bike, the gate, your line to turn 1.","Do not predict finishing positions or rank rivals before the gate; it limits you.","Focus on your own gate prep, not the riders beside you.","Moderate caffeine; too much leaves you tense. Try any supplement or caffeine at practice, never new on race day.","After the start, park thoughts about the last moto, the result and what others think.","Over-trying and self-pressure (expecting a podium, feeling outclassed) tighten the grip and bring on arm pump."],"faults":[{"fault":"Psyched out on the line","looks_like":"Rider watching other riders, fidgeting, late off the gate.","why":"Attention on rivals and outcome, not on the routine.","fix":"Same pre-race routine every time, breathing, one cue at a time."}],"drills":[{"name":"Pre-gate routine rehearsal","how":"Write a short routine (breaths, gear, check, line) and use it before every practice start.","progression":"Use it at a practice day, then at a race.","done_when":"It runs the same at a race as at practice."}]},"arm_pump_fitness":{"keys":["Aim for most of the hold from the legs (one coach suggests roughly 70 percent legs, 30 percent hands).","Use jumps and straights to relax the hands briefly.","Arm pump often comes back after a break from riding, when riding more than usual, or from race-day nerves and a faster pace than practice.","Ease into the first laps rather than going full speed immediately.","Stay active between ride days (cycling, jump rope, gym), and plan rest days.","A stiff fork that chatters into the arms, hard-to-reach or sticky controls and a tight clutch cable all add grip effort.","Practise at closer to race pace (ride with faster riders) so race day is not a shock."],"faults":[{"fault":"Squatting low with weak leg grip","looks_like":"Hips low behind the pegs, knees off the bike, forearms hard after a few laps.","why":"Legs are not holding the bike so the hands do.","fix":"Taller attack position, knees in, grip with legs."}],"pro_tips":["Many pros warm up on a stationary bike before racing; jogging in place or dynamic stretches work without one.","Fasciotomy surgery exists for chronic arm pump but results are not guaranteed; any consideration is for a doctor, after technique, fitness and setup are fixed."],"coaches_differ":["Forearm strength training: Risk Racing recommends grip trainers and forearm work, built up gradually; the American Public University piece argues extra forearm bulk leaves less room in the fascia and can make arm pump worse, and Bike Sport NZ advises against building muscle mass. All agree time on the bike and cardio help most.","Diet claims (avoid sugar, specific foods) and icing or massage advice come from coaching articles, not medical studies; BAK should present them as optional, not proven."]},"youth_coaching":{"keys":["Let riding be the child's idea; do not push, bribe or hint.","Short, positive sessions; stop while it is still fun.","One skill at a time, in order: balance (sit and walk the bike), throttle, braking, then turns, posture and pace.","Throttle first on a stand or with the engine off-ground: slow twists, then short on-off.","Teach both brakes: rear to slow, front to stop firmly; drill stopping until automatic.","Open the throttle limiter only as control improves.","Coach face to face at their level (kneel in front of the bike) so you can read their reactions; plain words, no technical detail.","Correct one habit on one section at a time, right after it happens, patiently.","Kids should not copy what pros do on big bikes; much of it does not suit small bikes.","Racing experience in varied conditions helps kids keep their skills when emotions run high.","After a race, react the same way whether they won or struggled; name one or two things they did well."],"faults":[{"fault":"Parent pushing past the child's comfort","looks_like":"Child hesitant, crying, or riding tense on features they did not choose.","why":"Parent focus on results or keeping up with others.","fix":"Let the child set the pace; return to features they ride happily."},{"fault":"Too many instructions at once","looks_like":"Child freezes or ignores cues; nothing changes.","why":"Over-explaining, technical language.","fix":"One simple cue per session block, praise when it shows."},{"fault":"Skipping steps","looks_like":"Child has speed but cannot stop or balance at walking pace.","why":"Moving to speed before balance and braking are solid.","fix":"Go back to balance and stopping drills on flat open ground."}],"drills":[{"name":"Stop on the mark","how":"Flat open area, limiter low; ride to a cone and stop using both brakes.","progression":"Slightly more speed and a later cone only once stops are smooth and straight.","done_when":"Child stops at the cone without skidding, every time."},{"name":"Stand-up and feet-on-pegs","how":"Easy loops standing, elbows up, feet always on the pegs.","progression":"Add gentle turns, then small rollers.","done_when":"Child stands without being reminded on straights."}],"pro_tips":["A professional coach can work better than a parent for some kids; parent coaching is harder to make work.","Readiness depends on size and on following instructions, not age alone: feet reach the ground, can listen and stop.","No gear, no ride: helmet, goggles, gloves, boots and pads every time."]},"vet_returning_riders":{"keys":["Fitness matters more than age; build cardio and strength before the first rides back.","Start on practice days at a calm pace; tabletops before doubles, and rebuild basics first (standing, knee grip, braking).","Crashes cost more with age (bones and time off work); ride a margin under your limit even after you feel comfortable.","Replace old gear: helmets and boots age; full protection.","Set suspension for your weight.","A smaller or milder bike (125, 250 two-stroke, 250F or 350 rather than a 450) is a common, sensible choice for returning riders.","Race your age class where there is one; mixing it with young racers led to repeat injuries for some.","Consistent riding a few days a month is enough to enjoy it without wearing the body out."],"faults":[{"fault":"Riding at old speed on old memory","looks_like":"Returning rider hits jumps and pace they rode years ago in the first session.","why":"Muscle memory outruns current fitness and reactions.","fix":"Staged return: basics, small features, then build over weeks; consider a lesson."}],"pro_tips":["A few private lessons cost less than an injury or bike repairs."],"coaches_differ":["Bike choice for returning vets: forum riders lean toward 125s, 250 two-strokes or 350s for less fatigue; others ride 450s geared tall. No coach source settled it; treat as preference."]}};
/** Which skills a question is about, from the rider's own words. */
const SKILL_WORDS:[string,RegExp][]=[
 ['starts',/\b(starts?|gate|holeshot|launch)\b/i],['race_starts_first_turn',/\b(first turn|gate pick|holeshot)\b/i],
 ['braking',/\b(brak(e|ing)|stoppie|braking bumps?)\b/i],['cornering_ruts',/\bruts?\b/i],['cornering_flat',/\b(flat (corner|turn)s?|corner(ing)?|turns?)\b/i],
 ['cornering_off_camber',/\boff[- ]?camber\b/i],['berms',/\bberms?\b/i],['race_lines',/\b(lines?|line choice)\b/i],
 ['corner_body_position',/\b(body position|outside (foot|peg)|weight the peg|sit(ting)? forward)\b/i],['throttle_clutch_traction',/\b(traction|clutch|throttle control|wheel ?spin)\b/i],
 ['jumps',/\b(jump(s|ing)?|double|triple|tabletop|case|casing|overjump|face kick)\b/i],['scrubbing',/\bscrub(bing)?\b/i],['whoops',/\bwhoops?\b/i],
 ['rhythm',/\brhythm\b/i],['sand',/\bsand(y)?\b/i],['mud',/\b(mud(dy)?|wet track)\b/i],['hardpack',/\b(hard ?pack|slick|dry slick)\b/i],['hills',/\b(hills?|uphill|downhill)\b/i],
 ['passing',/\b(pass(ing)?|block pass)\b/i],['race_day',/\b(race day|sighting lap|track walk|between motos)\b/i],['mental_game',/\b(nervous|nerves|confidence|mental|scared|fear|focus)\b/i],
 ['arm_pump_fitness',/\b(arm pump|fitness|tired|endurance)\b/i],['youth_coaching',/\b(my (son|daughter|kid)|youth|kids?|pee ?wee)\b/i],['vet_returning_riders',/\b(vet|getting back|returning|older rider|over 30|40\+)\b/i],
];
/** The extra coaching for up to three skills the rider's words point at; empty when the question isn't about riding technique. */
export function coachingExtrasFor(text:string,limit=3){
 const out:Record<string,(typeof coachingPass5)[string]>={};
 for(const [id,rx] of SKILL_WORDS){if(Object.keys(out).length>=limit)break;if(rx.test(text)&&coachingPass5[id])out[id]=coachingPass5[id];}
 return out;
}
